		fmt.Printf("Error compiling expression: %v\n", err)
		return
	}

	result = expr.Evaluate(nil)
	fmt.Printf("not(1) = %v (expected: false)\n", result)

	// Test not("") should return true
	fmt.Println("Testing not(\"\"):")
	expr, err = xpath.Compile("not(\"\")")
	if err != nil {
		fmt.Printf("Error compiling expression: %v\n", err)
		return
	}

	result = expr.Evaluate(nil)
	fmt.Printf("not(\"\") = %v (expected: true)\n", result)

	// Test not("non-empty") should return false
	fmt.Println("Testing not(\"hello\"):")
	expr, err = xpath.Compile("not(\"hello\")")
	if err != nil {
		fmt.Printf("Error compiling expression: %v\n", err)
		return
	}

	result = expr.Evaluate(nil)
	fmt.Printf("not(\"hello\") = %v (expected: false)\n", result)
}
EOF
